 * Type guard to check if an adapter is a Vercel AI SDK adapter
 */
export function isVercelAISDKAdapter(
  adapter: ProviderAdapter
): adapter is VercelAISDKAdapter {
  return adapter.name === 'vercel-ai-sdk';
}

